"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["15397"],{42820(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.tipo_etapa_snapshot.nota_de_origem_no_enem_sem_pontuacao","status":422,"titulo":"A c\xf3pia congelada do tipo de etapa com nota de origem no ENEM deve admitir compor a nota final"},"descricao":{"codigo":"uniplus.selecao.tipo_etapa_snapshot.nota_de_origem_no_enem_sem_pontuacao","requisitos":["UNI-REQ-0247"],"oQueAconteceu":["O tipo de uma etapa, na configura\xe7\xe3o congelada da vers\xe3o publicada, declara que a nota vem do ENEM e,\\nao mesmo tempo, que n\xe3o admite compor a nota final. A etapa de nota do ENEM comp\xf5e a m\xe9dia do\\ncandidato; um tipo com nota do ENEM que n\xe3o pontua reporia uma etapa que n\xe3o entra na m\xe9dia.","Cada etapa do processo congela uma c\xf3pia do tipo de etapa escolhido no cadastro de Configura\xe7\xe3o:\\no que identifica o tipo (origem, c\xf3digo, nome, se a nota vem do ENEM) e o que ele admite como car\xe1ter da\\netapa, isto \xe9, se as etapas do tipo podem compor a nota final e se podem eliminar candidato. A c\xf3pia\\ncongelada n\xe3o muda quando o cadastro muda depois.","O cadastro de tipos de etapa j\xe1 recusa essa combina\xe7\xe3o\\n([`nota_de_origem_no_enem_exige_pontuacao`](/erros/uniplus.configuracao.tipo_etapa.nota_de_origem_no_enem_exige_pontuacao)),\\ne a c\xf3pia congelada carrega a mesma garantia.","Este c\xf3digo aparece quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o publicada: em toda\\nopera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a\\nconsulta dos formul\xe1rios, as opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho\\nda p\xe1gina). Antes disso, o sistema confere a integridade dos bytes congelados: bytes alterados depois\\ndo congelamento s\xe3o recusados por [`integridade_violada`](/erros/uniplus.selecao.envelope_codec.integridade_violada) e n\xe3o chegam a esta\\ncausa. Pelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz esse defeito, porque o\\ncadastro de tipos de etapa o recusa antes. A recusa sai como viola\xe7\xe3o \xfanica, sem a lista `errors[]`, e\\nse refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["O pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a configura\xe7\xe3o congelada da vers\xe3o publicada,\\ne redefinir as etapas do processo n\xe3o a corrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Retifica\xe7\xe3o em ato \xfanico","Defini\xe7\xe3o de etapas e do cronograma das fases de processo publicado, quando declaram atos","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Tipo etapa snapshot"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);